BEGIN READ ONLY;
SELECT json_build_object('kind','registration','actor',u.username,'header',r.id,'status',r."statusCode",'header_version',r."currentRevision",'identity_version',i."currentRevision",'identity_status',i."currentStatusCode",'included',i."populationIncluded",'pointer_set',i."capacityReservationId" IS NOT NULL,'saved_revisions',(SELECT count(*) FROM "ActivityRegistrationRevision" x WHERE x."registrationId"=r.id),'participation_versions',(SELECT count(*) FROM "ActivityParticipationRevision" x WHERE x."identityId"=i.id),'active_reservations',(SELECT count(*) FROM "CapacityReservation" c WHERE c."identityId"=i.id AND c.status='active'),'role',u.role,'direct_bindings',(SELECT count(*) FROM role_bindings b WHERE b."principalId" IN (u.id,u."memberId"))) FROM "ActivityRegistration" r JOIN "User" u ON r."memberId"=u."memberId" JOIN "ActivityParticipationIdentity" i ON i."registrationId"=r.id WHERE r."activityId"=:'target' AND u.username IN ('t43-user-a','t43-user-b') ORDER BY u.username;
SELECT json_build_object('kind','bucket','scope',"scopeTypeCode",'used',occupied,'version',version) FROM "ActivityCapacityBucket" WHERE "activityId"=:'target' ORDER BY "scopeTypeCode";
SELECT json_build_object('kind','audit','event',a.event,'reqId',coalesce(a.context->>'requestId',a.context->>'reqId'),'actor',u.username,'resource',a."resourceId",'success',a.success) FROM audit_logs a JOIN "User" u ON u.id=a."actorUserId" WHERE u.username IN ('t43-user-a','t43-user-b') AND a.event IN ('registration.review','registration.create') ORDER BY a."createdAt",a.id;
SELECT json_build_object('kind','outbox','id',id,'type',"eventType",'aggregate',"aggregateType",'key_hash',md5("eventKey"),'state',status,'attempts',attempts,'completed',"completedAt" IS NOT NULL) FROM notification_outbox_intents ORDER BY "createdAt",id;
SELECT json_build_object('kind','population','revision',"populationRevision",'evidence_revision',"evidenceRevision",'version',version) FROM "ActivityEvidenceState" WHERE "activityId"=:'target';
ROLLBACK;
